    async function showAccount(){
      const account=currentAccount;
      if(!account){auth('login');return}
      if(isOwnerEmail(account.email)){await showOwnerAccount(account);return}
      open('<div class="auth-shell"><section class="auth-form"><div class="auth-brand"><span class="auth-mark">P</span><span>PUNJAB CSC<small>SECURE CUSTOMER ACCOUNT</small></span></div><div class="auth-heading"><span>ACCOUNT DASHBOARD</span><h2 id="account-name">Your account</h2><p id="account-mobile"></p></div><p class="password-note">Email and password protect this account. Files are stored only if you choose the separate private-copy consent.</p><h3>My applications</h3><div id="account-applications" class="password-note" aria-live="polite">Loading your applications‚Ä¶</div><button class="auth-switch" type="button" id="account-logout">Sign out</button></section><aside class="auth-welcome"><span class="welcome-kicker">YOUR PUNJAB CSC</span><h2>Private account access.</h2><p>Application records and document copies are restricted to your signed-in account.</p><div class="welcome-points"><span>‚ú¶ &nbsp; Private account session</span><span>‚ú¶ &nbsp; Your requests only</span><span>‚ú¶ &nbsp; Delete requests from this account</span></div></aside></div>');
      modal.classList.add('auth-dialog');
      body.querySelector('#account-name').textContent=account.name;
      body.querySelector('#account-mobile').textContent=(account.email||'')+(account.mobile?' ¬∑ WhatsApp '+account.mobile:'');
      const list=body.querySelector('#account-applications');
      try{
        const applications=await window.DeepCSCBackend.listApplications();list.replaceChildren();
        if(!applications.length)list.textContent='No applications are linked to this account yet.';
        for(const application of applications){
          const card=document.createElement('article'),title=document.createElement('strong'),status=document.createElement('p');
          card.style.cssText='padding:12px;margin:9px 0;border:1px solid #dce8e4;border-radius:9px;background:#fff';
          title.textContent=application.service;
          status.textContent=application.status+' ¬∑ '+new Date(application.created_at).toLocaleDateString();
          card.append(title,status);
          const docs=application.customer_documents||[];
          if(docs.length){const fileList=document.createElement('small');fileList.textContent=docs.length+' private document copy/copies stored';card.append(fileList)}
          const remove=document.createElement('button');remove.type='button';remove.className='auth-switch';remove.textContent='Delete request and private files';
          remove.onclick=async()=>{if(!confirm('Delete this request and any private document copies from your Punjab CSC account? This cannot remove files already sent in WhatsApp.'))return;remove.disabled=true;try{await window.DeepCSCBackend.deleteApplication(application.id);await showAccount()}catch(error){remove.disabled=false;notify(error.message)}};
          card.append(remove);list.append(card);
        }
      }catch(error){list.textContent=error.message}
      body.querySelector('#account-logout').onclick=async()=>{await window.DeepCSCBackend.signOut();clearSignedIn();modal.close();notify('Signed out.')};
    }
