    if(reviewForm)reviewForm.onsubmit=(event)=>{event.preventDefault();if(!reviewForm.reportValidity())return;const data=new FormData(reviewForm),review=String(data.get('review')||'').trim(),words=review.split(/\s+/).filter(Boolean).length;if(words<50){notify(pageCopy[currentLanguage].reviewShort);reviewText.focus();return}const publishConsent=data.get('publishConsent')==='on';whatsapp(`Punjab CSC customer feedback\nName: ${String(data.get('name')||'').trim()}\nRating: ${data.get('rating')} out of 5 stars\nReview (${words} words):\n${review}\n\nCustomer asked to send this feedback for review. Permission to contact about possible public display: ${publishConsent?'Yes':'No'}. Do not publish without separate owner approval.`)};
